import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.BXzK3EA4.js";const o="/assets/Iifl_2.hw5JnSy9.PNG",s="/assets/IIfl_3.By64nRG2.PNG",l="/assets/iifl_4%20(2).BJQxdQWV.PNG",n="/assets/IIfl_5.CPA7St2m.PNG",p="/assets/Iifl_6%20(1).U4nYnAz_.PNG",c="/assets/Iifl_7.DYDyJioR.PNG",y=JSON.parse('{"title":"IIFL Capital","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/iifl-capital.md","filePath":"connect-brokers/brokers/iifl-capital.md"}'),d={name:"connect-brokers/brokers/iifl-capital.md"};function h(g,e,u,f,I,m){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="iifl-capital" tabindex="-1">IIFL Capital <a class="header-anchor" href="#iifl-capital" aria-label="Permalink to &quot;IIFL Capital&quot;">​</a></h1><p>Tradeboard connects to IIFL Capital through their Markets&#39; APIs developer portal. You&#39;ll need <br> an active IIFL Capital trading account and a static public IP before you start, since IIFL whitelists the IP that&#39;s allowed to call your app.</p><p><strong>Prerequisites</strong></p><ul><li>An active IIFL Capital trading account (Client ID / PAN handy)</li><li>A static public IP address, which IIFL whitelists this IP and rejects API calls from anywhere else</li><li>Tradeboard running locally or on a host whose outbound IP matches what you&#39;ll register</li></ul><p><strong>Step 1: Visit the IIFL Markets&#39; APIs portal</strong></p><p>Go to <a href="https://developers.iiflcapital.com/" target="_blank" rel="noreferrer">https://markets.iiflcapital.com</a></p><p>Click Login / Sign Up at the top right and choose As Individual Trader.</p><figure><img src="'+o+'" alt=""><figcaption></figcaption></figure><p><strong>Step 2: Log in to the Developer Portal</strong></p><p>Sign in with your IIFL credentials. Email, Mobile, Client ID, or PAN works. Use the same <br> password you use for the IIFL trading platform.</p><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p><strong>Step 3: Open &quot;My Apps&quot;</strong></p><p>After login you land on the My Apps dashboard at developers.iiflcapital.com. Your IIFL <br> Client ID is shown in the greeting.</p><p>If this is your first time, the apps list will be empty. Click Create App in the top-right.</p><figure><img src="'+l+'" alt=""><figcaption></figcaption></figure><p><strong>Step 4: Create the Tradeboard App</strong></p><p>Fill the Create App form</p><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p>Click Submit.</p><p><strong>Important:</strong> The Redirect URL must match <a href="http://127.0.0.1:5000/iiflcapital/callback" target="_blank" rel="noreferrer">http://127.0.0.1:5000/iiflcapital/callback</a> exactly if you&#39;re running Tradeboard locally on the default port. If you&#39;ve changed HOST_SERVER in your .env, replace 127.0.0.1:5000 with your actual host and port.</p><p>The Primary Static IP must match the public IP from which Tradeboard will call IIFL. Use <a href="https://www.whatismyip.com" target="_blank" rel="noreferrer">https://www.whatismyip.com</a> to check. If your IP is dynamic (typical for home broadband), API calls will fail intermittently, so you&#39;ll need a fixed-IP setup or VPS.</p><p><strong>Step 5: Locate your App Key and App Secret</strong></p><p>After creation, your app shows up on the My Apps page with status Active. Click the <br> three-dot menu (⋮) on the app row and choose View All Details.</p><figure><img src="'+p+'" alt=""><figcaption></figcaption></figure><figure><img src="'+c+`" alt=""><figcaption></figcaption></figure><p>The View Details modal shows everything you need:</p><ul><li>App Name: friendly name only, not used in Tradeboard</li><li>Redirect URL: should match what you entered</li><li>Primary Static IP: for reference</li><li>Algo Registration Type: for reference</li><li>App Key: this becomes BROKER_API_KEY</li><li>App Secret Key: this becomes BROKER_API_SECRET</li></ul><p>If you ever lose the App Secret, use Regenerate App Secret from the same ⋮ menu. Existing Tradeboard sessions will need to log in again after rotation.</p><p><strong>Step 6: Configure Tradeboard</strong></p><p>Open your Tradeboard .env file and set:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_app_key_here&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_app_secret_key_here&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/iiflcapital/callback&#39;</span></span></code></pre></div><p>Save and restart Tradeboard.</p><p>Integrating Tradeboard with IIFL Capital&#39;s API opens up possibilities for automated trading strategies, providing a powerful tool for traders and developers to exploit market opportunities efficiently. It&#39;s essential to follow best practices for API integration, including handling rate limits, managing API keys securely, and ensuring robust error handling and logging mechanisms are in place.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/iiflcapital/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>BCD</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,36)])])}const b=t(d,[["render",h]]);export{y as __pageData,b as default};
